if(command.startsWith('large-'))await runLargeCLI(command.slice(6),options,directory);
else if(command==='help')console.log(`Measurements workspace, Node >=22.16\n\nreconciliation-catalogue|reconciliation-reports --workspace ./data\nreconciliation-groups --workspace ./data --file scope.json\nreconciliation-group --workspace ./data --id LOGICAL_KEY\nreconciliation-decide|reconciliation-save-report --workspace ./data --file reviewed-input.json\nreconciliation-report --workspace ./data --id REPORT_ID --format json|csv|html --output report.json\n\nflow-catalogue --workspace ./data\nflow-inspect|flow-preview|flow-save|flow-receive|flow-compare --workspace ./data --file input.json\nflow-read|flow-daily|flow-periods|flow-samples --workspace ./data --id ID --output result.json\n\nlarge-prepare|large-import --workspace ./data --file original.csv --kind wqp --label Source\nlarge-commit --workspace ./data --intake ID\nlarge-status --workspace ./data\nlarge-export --workspace ./data --output ./complete-edition\nlarge-receive --workspace ./empty-data --file complete-edition/project.zip\n\ncollection-preview|collection-receive --workspace ./data --manifest collection.json --source-root ./originals\ncollection-publish --workspace ./data --id COLLECTION_SHA\ncollections --workspace ./data\nserve --workspace ./data --port 3101\npreview|import --workspace ./data --kind wqp|stations|usgs-daily --file input.csv --label Source\nfetch --workspace ./data --kind wqp|stations|usgs-daily --station USGS-... --from YYYY-MM-DD --to YYYY-MM-DD\nsummary|records|calibration|export|portable --workspace ./data --output result.json\nreceive --workspace ./empty-data --file complete-workspace.json\nmap --workspace ./data --station ORG-ID --reach r1 --reviewer Name --reason Rationale\nreview --workspace ./data --id HASH --state include|exclude|pending --reviewer Name --reason Rationale\nloads --workspace ./data --station ORG-ID --flow-station USGS-ID --parameter tn|tp --reason Rationale\n\nThe server also exposes the original-app integration API /api/measurement-workspace.\n`);
