        "before": "if(b.dataset.tab){stopFlow();tab=b.dataset.tab;",
        "after": "if(b.dataset.tab){stopFlow();stopSourceReview();tab=b.dataset.tab;"
      },
      {
        "before": "destroy(){dead=true;intake.destroy();stopFlow();controller.abort();",
        "after": "destroy(){dead=true;intake.destroy();stopFlow();stopSourceReview();controller.abort();"
      }
    ],
    "reverse_exact": true,
    "script_parse_count": 8
