  function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  host.addEventListener('submit',event=>{if(event.target.closest('.mf'))return;event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));task(async()=>{
    if(form.id==='mw-upload'){if(data.file.size>128*1024*1024)throw new Error('File exceeds the 128 MiB per-source process limit.');source={kind:data.kind,label:data.label,text:await readText(data.file),mapping:JSON.parse(data.mapping||'{}')};preview=await api('/preview','POST',source);renderPreview();message(`Inspected ${preview.rows} complete source rows. Review the counts, then import.`);}
    if(form.id==='mw-provider'){message('Retrieving complete provider response…');const result=await api('/provider-fetch','POST',data);source=result.source;preview=result.preview;renderPreview();message(`Retrieved ${preview.rows} rows. Inspect before committing.`);}
    if(form.id==='mw-filter'){filters=data;offset=0;selected=null;await loadRecords();message('Measurement filters applied.');}
    if(form.id==='mw-review'){const response=await api('/records/'+selected.id+'/review','PUT',{...data,selectVersion:data.selectVersion==='on',expectedRevision:summary.revision});summary.revision=response.revision;selected=response.record;statBar();await loadRecords();message('Review saved with its rationale.');}
    if(form.dataset.stationForm){await api('/stations/'+encodeURIComponent(form.dataset.stationForm)+'/mapping','PUT',{...data,expectedRevision:summary.revision});await refresh();message('Native reach assignment saved.');}
    if(form.id==='mw-loads'){const report=await api('/paired-loads','POST',data);await showResult(report,report.exportId);message('Paired-load result saved. Inspect both populations and download the readable report or complete data.');}
    if(form.id==='mw-receive'){const payload=JSON.parse(await readText(data.file));await api('/receive','POST',payload);await refresh();message('Complete workspace received; originals and canonical values verified.');}
  });},{signal:controller.signal});
  host.addEventListener('click',event=>{const a=event.target.closest('a[download]');if(a&&transport&&a.getAttribute('href').startsWith(base)){event.preventDefault();task(async()=>{const r=await transport(a.getAttribute('href').slice(base.length),'GET');const text=await r.text();if(!r.ok)throw new Error(text);download(a.textContent.includes('CSV')?'measurements.csv':a.textContent.includes('Original')?'original-source.txt':'rejected-rows.json',text,r.type||'text/plain');});return;}const b=event.target.closest('button');if(!b||!host.contains(b))return;if(b.type==='submit'&&b.form)return;task(async()=>{
    if(b.dataset.tab){stopFlow();tab=b.dataset.tab;selected=null;if(tab==='records')await loadRecords();else if(tab==='results')await loadHistory();else render();return;}
