    if(action==='query'){const data=Object.fromEntries(new FormData(area.querySelector('#mw-provider'))),q=await api('/provider-query','POST',data);const box=area.querySelector('#mw-query');box.replaceChildren();const p=document.createElement('p');p.textContent=q.url; p.className='mw-mono';box.append(p);message('Complete source query prepared; use an authorized network-enabled session to retrieve this exact file when needed.');}
    if(action==='commit'){if(!source||!preview)throw new Error('Inspect a complete source first');const result=await api('/imports','POST',{...source,contentSha:preview.contentSha});source=null;preview=null;await refresh();message(result.duplicate?'This exact source is already retained; no duplicates were created.':`Imported ${result.rows} source rows; retained ${result.rejectedCount} rejected rows with reasons.`);}
    if(action==='next'){offset+=50;await loadRecords();}if(action==='previous'){offset=Math.max(0,offset-50);await loadRecords();}
    if(action==='close-detail'){selected=null;area.querySelector('#mw-inspector').replaceChildren();}
    if(action==='calibration'){const report=await api('/calibration','POST',{});await showResult(report,report.exportId);message('Reviewed input result saved. Accepted observations, exclusions and source references are available below.');}
    if(action==='portable'){message('Exporting complete original files and histories…');download('upper-savannah-measurements.json',await api('/portable'));message('Complete editable workspace exported.');}
  });},{signal:controller.signal});
  task(refresh);
  return {refresh:()=>task(refresh),destroy(){dead=true;intake.destroy();stopFlow();controller.abort();style.remove();host.replaceChildren();host.classList.remove('mw');}};
}

import {mountGuidedIntake} from './measured_intake.mjs';
import {describeResult,renderResult,resultHTML,resultCSV,renderSourceInspection,reasonText} from './measured_results.mjs';
