  function recordTable(rows,inspect=true){if(!rows?.length)return '<p class="mw-empty">No measurements in this selection.</p>';return `<div class="mw-table-wrap"><table><thead><tr><th>Source date</th><th>Station</th><th>Constituent</th><th>Result</th><th>Fraction / basis</th><th>Review / eligibility</th>${inspect?'<th>Inspect</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.sampledDate||'—')}</td><td class="mw-mono">${esc(r.stationId||r.id)}</td><td>${esc(r.parameter||r.name||'Station')}</td><td class="mw-number">${r.censor&&r.censor!=='none'?esc((r.censor==='left'?'≤ ':'≥ ')+num(r.censor==='left'?r.upper:r.lower)):num(r.value)} ${esc(r.unit||'')}</td><td>${esc(r.fraction||'—')} / ${esc(r.basis||'—')}</td><td>${r.eligible?(r.eligible.ok?'Usable measured input':esc(r.eligible.reasons.map(reasonText).join(' '))):esc((r.issues||[]).join(', ')||'No parse flags')}</td>${inspect?`<td><button data-record="${esc(r.id)}">Inspect</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
