    if(action==='commit'){if(!source||!preview)throw new Error('Inspect a complete source first');const result=await api('/imports','POST',{...source,contentSha:preview.contentSha});source=null;preview=null;await refresh();message(result.duplicate?'This exact source is already retained; no duplicates were created.':`Imported ${result.rows} source rows; retained ${result.rejectedCount} rejected rows with reasons.`);}
    if(action==='next'){offset+=50;await loadRecords();}if(action==='previous'){offset=Math.max(0,offset-50);await loadRecords();}
